     * دالة ذكية لفحص الحالة الصحية بناءً على المكتبة المرجعية
     */
    private static $cachedTiers = null;
    private static $scoreCache = [];

    /**
     * دالة ذكية وفائقة السرعة لفحص الحالة الصحية
     */
    public static function calculateHealthScore($description)
    {
        if (empty($description)) return 0;
        
        $description = mb_strtolower(trim($description));

        if (isset(self::$scoreCache[$description])) {
            return self::$scoreCache[$description];
        }
        
        // 1. استخدام "الخرائط الذهنية" للبحث الفوري (O(1)) في الـ 100 ألف سطر
        if (self::$cachedTiers === null) {
            $tiers = self::getTiers();
            self::$cachedTiers = [
                'critical' => array_flip($tiers['critical']),
                'serious' => array_flip($tiers['serious']),
                'moderate' => array_flip($tiers['moderate']),
                'stable' => array_flip($tiers['stable']),
            ];
        }

        if (isset(self::$cachedTiers['critical'][$description])) return 80;
        if (isset(self::$cachedTiers['serious'][$description])) return 55;
        if (isset(self::$cachedTiers['moderate'][$description])) return 30;
        if (isset(self::$cachedTiers['stable'][$description])) return 10;

        // 2. خطة بديلة: البحث عن "الكلمات المفتاحية" الأساسية إذا لم يتطابق النص كاملاً
        $keywords = [
            'critical' => ['سرطان', 'كانسر', 'فشل', 'غسيل', 'قلب', 'شرايين', 'كبد', 'لوكيميا', 'كيماوي', 'إشعاعي', 'تضخم'],
            'serious' => ['شلل', 'بتر', 'جلطة', 'إصابة حرب', 'نزيف', 'كسر', 'بلاتين', 'ضمور', 'تصلب'],
            'moderate' => ['إعاقة', 'ديسك', 'غضروف', 'صرع', 'توحد', 'متلازمة', 'ثقب', 'قدم سكرية'],
            'stable' => ['سكري', 'ضغط', 'شظايا', 'ربو', 'حساسية', 'شيخوخة', 'كبر سن', 'عرق نسا', 'سوء تغذية']
        ];

        foreach ($keywords['critical'] as $w) if (mb_strpos($description, $w) !== false) return 80;
        foreach ($keywords['serious'] as $w) if (mb_strpos($description, $w) !== false) return 55;
        foreach ($keywords['moderate'] as $w) if (mb_strpos($description, $w) !== false) return 30;
        foreach ($keywords['stable'] as $w) if (mb_strpos($description, $w) !== false) return 10;

        return 0;
    }
}